/**
 * Login Feature — Generated Test Suite
 * Feature:  Azure AD B2C authentication on fra-vanilla-preprod
 * Scenarios: TC-001 – TC-011 (11 tests: 2 × P0, 7 × P1, 2 × P2)
 * Generated by: QE-AI test-implementer
 *
 * ⚠️  TC-002, TC-009, TC-010, TC-011 involve post-login authenticated state.
 *     Locators for the authenticated header and logout button are marked with
 *     // TODO comments in HomePage.ts — update after a manual authenticated run.
 */
import { test, expect } from '@fixtures';
import { config } from '@config/index';
import { DataGenerator } from '@utils/DataGenerator';

test.describe(`@Login Login — ${config.displayName} [${config.environment}]`, () => {

  // ===========================================================================
  // P0 — Smoke (must pass on every run)
  // ===========================================================================

  test('@P0 @Smoke TC-001: Valid credentials redirect away from login page', async ({ loginModule, page }) => {
    await test.step('Login with configured OPCO credentials', async () => {
      await loginModule.doLogin();
    });

    await test.step('Assert browser is no longer on the login domain', async () => {
      await expect(page).not.toHaveURL(/\/login|signin|identifier|b2clogin/i);
    });

    await test.step('Assert page has a non-empty title', async () => {
      await expect(page).toHaveTitle(/.+/);
    });
  });

  test('@P0 @Smoke TC-002: Authenticated state is visible in the page header after login', async ({ loginModule, homePage, page }) => {
    await test.step('Login with valid credentials', async () => {
      await loginModule.doLogin();
    });

    await test.step('Navigate to homepage', async () => {
      await homePage.goHome();
    });

    await test.step('Verify authenticated user element is present in header', async () => {
      // TODO: update userAccountBtn locator in HomePage.ts after authenticated browse
      await expect(homePage.userAccountBtn()).toBeVisible();
    });

    await test.step('Verify Login link is no longer visible (user is logged in)', async () => {
      await expect(homePage.loginLink()).not.toBeVisible();
    });
  });

  // ===========================================================================
  // P1 — Core functional scenarios
  // ===========================================================================

  test('@P1 @Functional TC-003: Accessing a protected route while logged out redirects to login', async ({ loginModule, page }) => {
    await test.step('Navigate directly to a protected account route', async () => {
      await loginModule.verifyProtectedRouteRedirect('/account/en-gb/users');
    });

    await test.step('Assert URL contains login indicators', async () => {
      await expect(page).toHaveURL(/login|signin|identifier|b2clogin/i);
    });
  });

  test('@P1 @Negative TC-004: Invalid email format shows an error message', async ({ loginPage, page }) => {
    const invalidEmail = `${DataGenerator.randomString(6)}@@invalid`;

    await test.step('Navigate to the login page', async () => {
      await loginPage.navigate(config.loginPath);
      await loginPage.waitForPageLoad();
      await loginPage.dismissCookieBanner();
    });

    await test.step(`Enter an invalidly formatted email: "${invalidEmail}"`, async () => {
      await loginPage.fillEmail(invalidEmail);
    });

    await test.step('Attempt to continue / submit the form', async () => {
      await loginPage.clickContinue();
    });

    await test.step('Verify an error or validation message is visible', async () => {
      await expect(loginPage.errorMessage()).toBeVisible();
    });
  });

  test('@P1 @Negative TC-005: Wrong password shows an error message', async ({ loginModule, loginPage }) => {
    const wrongPassword = DataGenerator.randomString(12);

    await test.step('Attempt login with correct email but wrong password', async () => {
      await loginModule.doLogin(config.username, wrongPassword);
    });

    await test.step('Verify error message is displayed', async () => {
      await loginModule.verifyLoginFailed();
    });
  });

  test('@P1 @Negative TC-006: Non-existent user account shows an error message', async ({ loginModule, loginPage }) => {
    const nonExistentEmail = DataGenerator.randomEmail();
    const anyPassword = DataGenerator.randomString(10);

    await test.step('Attempt login with a non-existent email address', async () => {
      await loginModule.doLogin(nonExistentEmail, anyPassword);
    });

    await test.step('Verify error message is displayed', async () => {
      await loginModule.verifyLoginFailed();
    });
  });

  test('@P1 @Negative TC-007: Submitting empty email field shows a validation message', async ({ loginPage }) => {
    await test.step('Navigate to the login page', async () => {
      await loginPage.navigate(config.loginPath);
      await loginPage.waitForPageLoad();
      await loginPage.dismissCookieBanner();
    });

    await test.step('Leave the email field empty and attempt to continue', async () => {
      await loginPage.fillEmail('');
      await loginPage.clickContinue();
    });

    await test.step('Verify a validation error is shown', async () => {
      await expect(loginPage.errorMessage()).toBeVisible();
    });
  });

  test('@P1 @Negative TC-008: Submitting empty password field shows a validation message', async ({ loginPage }) => {
    await test.step('Navigate to the login page', async () => {
      await loginPage.navigate(config.loginPath);
      await loginPage.waitForPageLoad();
      await loginPage.dismissCookieBanner();
    });

    await test.step('Fill in the email and advance to the password step', async () => {
      await loginPage.fillEmail(config.username);
      await loginPage.checkHumanVerification();
      await loginPage.waitForAuth0CaptchaSolved();
      await loginPage.clickContinue();
    });

    await test.step('Leave the password field empty and attempt to sign in', async () => {
      await loginPage.fillPassword('');
      await loginPage.clickSignIn();
    });

    await test.step('Verify a validation error is shown', async () => {
      await expect(loginPage.errorMessage()).toBeVisible();
    });
  });

  test('@P1 @Functional TC-009: Authenticated user can successfully log out', async ({ loginModule, homePage, page }) => {
    await test.step('Login with valid credentials', async () => {
      await loginModule.doLogin();
    });

    await test.step('Navigate to the homepage', async () => {
      await homePage.goHome();
    });

    await test.step('Perform logout via account menu', async () => {
      // TODO: update HomePage logout locators after authenticated browse
      await loginModule.doLogout();
    });

    await test.step('Verify browser is redirected to the login page or homepage (logged-out state)', async () => {
      await expect(page).toHaveURL(/login|signin|identifier|\/$/i);
    });
  });

  test('@P1 @Functional TC-010: Session is cleared after logout — accessing protected route redirects to login', async ({ loginModule, homePage, page }) => {
    await test.step('Login with valid credentials', async () => {
      await loginModule.doLogin();
    });

    await test.step('Navigate to the homepage', async () => {
      await homePage.goHome();
    });

    await test.step('Perform logout', async () => {
      // TODO: update HomePage logout locators after authenticated browse
      await loginModule.doLogout();
    });

    await test.step('Navigate to a protected route post-logout', async () => {
      await page.goto('/account/en-gb/users');
    });

    await test.step('Verify browser is redirected to login — session is cleared', async () => {
      await expect(page).toHaveURL(/login|signin|identifier|b2clogin/i);
    });
  });

  // ===========================================================================
  // P2 — Edge cases
  // ===========================================================================

  test('@P2 @EdgeCase TC-011: Pressing browser back after logout does not restore the authenticated session', async ({ loginModule, homePage, page }) => {
    await test.step('Login with valid credentials', async () => {
      await loginModule.doLogin();
    });

    await test.step('Record the post-login URL', async () => {
      // URL captured implicitly — back-navigation below targets this URL
    });

    await test.step('Navigate to the homepage', async () => {
      await homePage.goHome();
    });

    await test.step('Perform logout', async () => {
      // TODO: update HomePage logout locators after authenticated browse
      await loginModule.doLogout();
    });

    await test.step('Press browser Back button to attempt to return to authenticated page', async () => {
      await page.goBack();
    });

    await test.step('Verify session is not restored — login prompt or redirect to login', async () => {
      // Either the page redirects to login, or the page is shown but the user is not authenticated
      const url = page.url();
      const isLoginPage = /login|signin|identifier|b2clogin/i.test(url);
      if (!isLoginPage) {
        // If browser cached the page, verify the user account element is NOT visible
        await expect(homePage.userAccountBtn()).not.toBeVisible({ timeout: 5_000 });
      } else {
        await expect(page).toHaveURL(/login|signin|identifier|b2clogin/i);
      }
    });
  });

});
